const size_t TrapDatabase::trapTableSize = 2051;

const TrapInfo *TrapDatabase::findTrap(llvm::StringRef name) const {
  // Try exact match first
  for (size_t i = 0; i < trapTableSize; ++i) {
    if (name == trapTable[i].name)
      return &trapTable[i];
  }

  // Try with underscore prefix stripped (C symbols often have leading _)
  if (!name.empty() && name[0] == '_') {
    llvm::StringRef stripped = name.substr(1);
    for (size_t i = 0; i < trapTableSize; ++i) {
      if (stripped == trapTable[i].name)
        return &trapTable[i];
    }
  }

  return nullptr;
}

llvm::ArrayRef<TrapInfo> TrapDatabase::getAllTraps() const {
  return llvm::ArrayRef<TrapInfo>(trapTable, trapTableSize);
}

